test('invoiceTotals calculates VAT on amount after discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 2 * 8500;
  const discount = subtotal * 10 / 100;
  const amountAfterDiscount = subtotal - discount;
  const vat = Math.round(amountAfterDiscount * 21 / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('invoiceTotals sums VAT for multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const sub1 = 2 * 8500;
  const sub2 = 100 * 37;
  const vat1 = Math.round(sub1 * 21 / 100);
  const vat2 = Math.round(sub2 * 9 / 100);
  assert.equal(totals.subtotal, sub1 + sub2);
  assert.equal(totals.vat, vat1 + vat2);
});

test('invoiceTotals with VAT-exempt products (vatRate 0)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 60000;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, subtotal);
});

test('invoiceTotals total = subtotal - discount + vat', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3, discountPercent: 15 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 10 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const expected = totals.subtotal - totals.discount + totals.vat;
  assert.equal(totals.total, expected);
});

