test('renderInvoiceText shows subtotal, discount, VAT and total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  const subtotalLine = lines.find(l => l.startsWith('Subtotal:'));
  const discountLine = lines.find(l => l.startsWith('Discount:'));
  const vatLine = lines.find(l => l.startsWith('VAT:'));
  const totalLine = lines.find(l => l.startsWith('Total:'));
  assert.ok(subtotalLine);
  assert.ok(discountLine);
  assert.ok(vatLine);
  assert.ok(totalLine);
});

test('renderInvoiceText does not show discount line when discount is zero', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /Subtotal:/);
  assert.match(text, /VAT:/);
  assert.match(text, /Total:/);
  assert.doesNotMatch(text, /Discount:/);
});

test('renderInvoiceText does not show VAT line when VAT is zero', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /Subtotal:/);
  assert.match(text, /Total:/);
  assert.doesNotMatch(text, /VAT:/);
});

test('renderInvoiceText VAT line is above total line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  const vatIndex = lines.findIndex(l => l.startsWith('VAT:'));
  const totalIndex = lines.findIndex(l => l.startsWith('Total:'));
  assert.ok(vatIndex >= 0);
  assert.ok(totalIndex >= 0);
  assert.ok(vatIndex < totalIndex);
});

