    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'STICKER', qty: 100 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = (5 * 8500) + (1 * 120000) + (100 * 50);
  const discount = subtotal * 2.5 / 100;
  const l1 = 5 * 8500;
  const d1 = l1 * 2.5 / 100;
  const v1 = Math.round((l1 - d1) * 21 / 100);
  const l2 = 1 * 120000;
  const d2 = l2 * 2.5 / 100;
  const v2 = Math.round((l2 - d2) * 21 / 100);
  const l3 = 100 * 50;
  const d3 = l3 * 2.5 / 100;
  const v3 = Math.round((l3 - d3) * 21 / 100);
  const vat = v1 + v2 + v3;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.total, subtotal - discount + vat);
});

