  const sub1 = 2 * 8500;
  const sub2 = 3 * 9500;
  const disc1 = sub1 * 10 / 100;
  const disc2 = sub2 * 20 / 100;
  const vat1 = Math.round((sub1 - disc1) * 21 / 100);
  const vat2 = Math.round((sub2 - disc2) * 21 / 100);
