test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 2, unitPrice: 8500 }), 17000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 1250 }), 1250);
  assert.equal(lineTotal({ qty: 10, unitPrice: 100 }), 1000);
});

test('invoiceTotals sums line totals for a single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 3 * 8500;
  const discount = subtotal * 5 / 100;
  const amountAfterDiscount = subtotal - discount;
  const vat = Math.round(amountAfterDiscount * 21 / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('invoiceTotals sums line totals for multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = (2 * 8500) + (3 * 9500);
  const discount = subtotal * 5 / 100;
  const amountAfterDiscount = subtotal - discount;
  const vat = Math.round(amountAfterDiscount * 21 / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('invoiceTotals calculates correctly with multiple varied items', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'STICKER', qty: 100 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = (5 * 8500) + (1 * 120000) + (100 * 50);
  const discount = subtotal * 2.5 / 100;
  const l1 = 5 * 8500;
  const d1 = l1 * 2.5 / 100;
  const v1 = Math.round((l1 - d1) * 21 / 100);
  const l2 = 1 * 120000;
  const d2 = l2 * 2.5 / 100;
  const v2 = Math.round((l2 - d2) * 21 / 100);
  const l3 = 100 * 50;
  const d3 = l3 * 2.5 / 100;
  const v3 = Math.round((l3 - d3) * 21 / 100);
  const vat = v1 + v2 + v3;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('invoiceTotals calculates discount correctly for a single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 2 * 8500;
  const discount = subtotal * 10 / 100;
  const amountAfterDiscount = subtotal - discount;
  const vat = Math.round(amountAfterDiscount * 21 / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('invoiceTotals sums discounts for multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 20 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const sub1 = 2 * 8500;
  const sub2 = 3 * 9500;
  const disc1 = sub1 * 10 / 100;
  const disc2 = sub2 * 20 / 100;
  const vat1 = Math.round((sub1 - disc1) * 21 / 100);
  const vat2 = Math.round((sub2 - disc2) * 21 / 100);
  assert.equal(totals.subtotal, sub1 + sub2);
  assert.equal(totals.discount, disc1 + disc2);
  assert.equal(totals.vat, vat1 + vat2);
  assert.equal(totals.total, (sub1 + sub2) - (disc1 + disc2) + (vat1 + vat2));
});

test('invoiceTotals returns 0 discount when customer has no tier discount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.discount, 0);
  const vat = Math.round(totals.subtotal * 21 / 100);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, totals.subtotal + vat);
});

test('invoiceTotals with 100% discount reduces total to 0', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 100 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.discount, 2 * 8500);
  assert.equal(totals.total, 0);
});

test('invoiceTotals clamps amounts at 0', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 100 }],
  });
  const totals = invoiceTotals(r.value);
  assert.ok(totals.subtotal >= 0);
  assert.ok(totals.discount >= 0);
  assert.ok(totals.total >= 0);
});

test('invoiceTotals with tier-based discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 2 * 8500;
  const expectedDiscount = subtotal * 5 / 100;
  const amountAfterDiscount = subtotal - expectedDiscount;
  const expectedVat = Math.round(amountAfterDiscount * 21 / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, subtotal - expectedDiscount + expectedVat);
});

test('invoiceTotals calculates VAT on amount after discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
