});

test('addLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const originalLineCount = r.value.lines.length;
  addLine(r.value, { sku: 'DEV-HOUR', qty: 1 });
  assert.equal(r.value.lines.length, originalLineCount);
});

test('addLine includes discountPercent for new lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = addLine(r.value, { sku: 'DEV-HOUR', qty: 1, discountPercent: 15 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].discountPercent, 15);
});

test('addLine applies tier discount to new lines when no explicit discount', () => {
  const r = createInvoice({
